import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Export comptable","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/caissier/export-comptable.md","filePath":"src/guide/caissier/export-comptable.md"}'),o={name:"guide/caissier/export-comptable.md"};function n(l,e,i,p,u,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="export-comptable" tabindex="-1">Export comptable <a class="header-anchor" href="#export-comptable" aria-label="Permalink to &quot;Export comptable&quot;">​</a></h1><p>Depuis la page <strong>Facturation</strong>, trois boutons vous permettent de télécharger les données financières de l&#39;établissement sous une forme exploitable par votre comptable ou pour vos propres archives. Chaque bouton télécharge le fichier immédiatement, sans réglage préalable.</p><table tabindex="0"><thead><tr><th>Bouton</th><th>Contenu du fichier</th><th>Usage typique</th></tr></thead><tbody><tr><td><strong>Exporter en CSV</strong></td><td>Un tableau brut de tous les paiements encaissés : élève, article de frais, montant, méthode, référence, date, et qui l&#39;a enregistré.</td><td>Vérifier ou trier les paiements dans un tableur.</td></tr><tr><td><strong>Exporter SYSCOHADA</strong></td><td>Un journal de caisse combiné : les encaissements (paiements reçus) et les décaissements (dépenses approuvées), classés par date avec un compte débit/crédit pour chaque mouvement.</td><td>Alimenter la comptabilité de l&#39;établissement selon le plan comptable SYSCOHADA.</td></tr><tr><td><strong>Exporter par classe</strong></td><td>Un relevé détaillé, classe par classe puis élève par élève : chaque article de frais avec le montant dû, le montant payé, le reste à payer et le pourcentage réglé.</td><td>Faire un point de situation avec un enseignant ou un directeur de site sur l&#39;état des paiements d&#39;une classe.</td></tr></tbody></table><h2 id="exporter-en-csv" tabindex="-1">Exporter en CSV <a class="header-anchor" href="#exporter-en-csv" aria-label="Permalink to &quot;Exporter en CSV&quot;">​</a></h2><p>Cliquez sur <strong>Exporter en CSV</strong> pour télécharger un fichier listant chaque paiement enregistré individuellement. Ce fichier est utile pour retrouver rapidement un paiement précis ou pour l&#39;importer dans un autre outil.</p><h2 id="exporter-au-format-syscohada" tabindex="-1">Exporter au format SYSCOHADA <a class="header-anchor" href="#exporter-au-format-syscohada" aria-label="Permalink to &quot;Exporter au format SYSCOHADA&quot;">​</a></h2><p>Cliquez sur <strong>Exporter SYSCOHADA</strong> pour télécharger un journal de caisse qui rapproche les paiements reçus (encaissements) et les dépenses déjà <strong>approuvées</strong> (décaissements) — voir <a href="/era-guide/guide/caissier/depenses.html">Dépenses</a>. Chaque ligne indique la date, le journal concerné, les comptes de débit et de crédit, un libellé et un montant, dans un format directement utilisable par un cabinet comptable travaillant avec le plan comptable SYSCOHADA.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Seules les dépenses déjà approuvées par un administrateur apparaissent dans cet export ; une dépense encore en attente n&#39;y figure pas.</p></div><h2 id="exporter-par-classe" tabindex="-1">Exporter par classe <a class="header-anchor" href="#exporter-par-classe" aria-label="Permalink to &quot;Exporter par classe&quot;">​</a></h2><p>Cliquez sur <strong>Exporter par classe</strong> pour télécharger un relevé qui détaille, pour chaque élève de chaque classe, l&#39;état de chaque article de frais (montant dû, montant payé, reste à payer, pourcentage réglé) ainsi que la liste de ses paiements. C&#39;est le format le plus adapté pour un suivi classe par classe.</p>',10)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
